function eventView(){const list=state.archive.filter(r=>r.type==='event').sort((a,b)=>(b.date||'').localeCompare(a.date||''));return {body:`<header class="large-title"><div><small>${plural(list.length,'круглий стіл','круглі столи','круглих столів')}</small><h1>Круглі столи</h1></div></header>
 ${list.length?`<section class="group"><div class="card">${list.map(r=>`<div class="row-wrap"><button class="row" data-action="event-open" data-id="${esc(r.id)}"><span class="avatar event">${icon('doc')}</span><span class="row-main"><b>${esc(r.title||'Без назви')}</b><small>${[date(r.date),...(r.data.products||[])].map(esc).join(' · ')}</small></span><span class="row-amount">${money(costTotal(r.data.items||[]))} ₴</span></button><button class="icon-btn more-btn" data-row-menu="${esc(r.id)}" aria-label="Дії: ${esc(r.title)}">${icon('more')}</button></div>`).join('')}</div></section>`:`<section class="group"><div class="card empty">${icon('doc','big')}<b>Ще немає круглих столів</b><p>Натисніть «Створити новий» внизу.</p></div></section>`}`,bar:`<button class="button pill" data-action="event-create">${icon('plus')}Створити новий</button>`}}
function eventEditView(){const e=state.event;e.city=CITY;const step=(n,t)=>`<span class="step-n">${n}</span>${t}`;return {title:e.archiveId?'Круглий стіл':'Новий круглий стіл',left:`<button class="round ghost" data-action="event-close" aria-label="Закрити">${icon('x')}</button>`,right:`<button class="text-btn" data-action="event-save">Зберегти</button>`,
 body:` <section class="doc-pair"><button class="doc-card" data-doc="order"><span class="doc-ic">${icon('doc')}</span><b>Наказ</b><small id="order-state"></small></button><button class="doc-card" data-doc="budget"><span class="doc-ic">${icon('list')}</span><b>Кошторис</b><small id="budget-state"></small></button></section>
 ${group(step(1,'Клініка'),`${pickField('Назва закладу','event.venue',e.venue,'clinics','event','placeholder="Виберіть або введіть клініку" maxlength="180"')}`)}
 ${group(step(2,'Дати'),`<div class="field-grid">${field('Дата наказу','event.orderDate',eventDates(e).orderDate,'date','required')}${field('Дата чеку','event.receiptDate',e.receiptDate||'','date','required')}</div><p class="hint" id="order-date"></p>`)}
 ${group(step(3,'Відповідальна особа'),`${pickField('ПІБ у давальному відмінку','event.person',e.person,'representatives','event','placeholder="Кузьмінській Уляні Іванівні" maxlength="180"')}`)}
 ${group(step(4,'Препарати'),`<div class="chips">${state.products.map(p=>`<button class="chip ${e.products.includes(p)?'checked':''}" data-product="${esc(p)}" aria-pressed="${e.products.includes(p)}">${e.products.includes(p)?icon('check'):''}${esc(p)}</button>`).join('')}</div><div class="inline-add"><input id="new-product" placeholder="Інший препарат" aria-label="Назва нового препарату" maxlength="80"><button class="round soft" data-action="add-product" aria-label="Додати препарат">${icon('plus')}</button></div>`)}
 ${group(step(5,'Витрати'),`<p class="hint" style="margin:-6px 2px 12px">Суму можна залишити порожньою, якщо її ще немає.</p><div class="budget-rows">${e.items.map((r,i)=>`<div class="budget-row"><input class="b-name" aria-label="Позиція ${i+1}" placeholder="Назва позиції" data-item="${i}" data-prop="name" value="${esc(r.name)}" maxlength="120"><button class="icon-btn" data-remove-item="${i}" aria-label="Видалити позицію ${i+1}">${icon('x')}</button><label class="mini"><span>К-сть</span><input data-item="${i}" data-prop="qty" type="number" inputmode="decimal" min="0.01" step="0.01" value="${r.qty}" aria-label="Кількість ${i+1}"></label><label class="mini"><span>Сума за од., ₴</span><input data-item="${i}" data-prop="price" type="number" inputmode="decimal" min="0" step="0.01" value="${Number(r.price)?r.price:''}" placeholder="—" aria-label="Ціна ${i+1}"></label><b class="b-total" data-line-total="${i}"></b></div>`).join('')}</div><button class="add-row" data-action="add-item">${icon('plus')}Додати позицію</button>`)}
`}}

/* ---------- Подорожній лист ---------- */
let fuelRows=[],fuelLoaded=false;
function prepareMonthly(){const t=state.travel;if(t.fuelMode!=='filled'){t.refill=travelCalc(t).refill??0;t.fuelMode='filled';}const bounds=monthBounds(t.from?.slice(0,7));if(bounds){Object.assign(t,bounds);t.rows.forEach(row=>{if(row.date<t.from||row.date>t.to)row.date=t.from;});}Object.assign(t,filledTravel(t));}
function previousLine(){const row=prevRecord(state.travel);if(!row)return '';const r=fuelMetrics(row),t=state.travel,same=Math.abs(Number(t.startFuel)-r.endFuel)<0.01&&Math.abs(Number(t.odometer)-r.endOdo)<0.01;return same?`<p class="hint">Початкові дані взято з ${esc(monthName(row.from).replace(/ р\.$/,''))}.</p>`:`<p class="hint">У ${esc(monthName(row.from).replace(/ р\.$/,''))} на приїзді було ${num(r.endFuel)} л і ${num(r.endOdo)} км, а тут введено інше.</p><div class="card-foot">${btn(icon('back')+'Взяти з попереднього місяця','fuel-previous','link')}</div>`}
function sumExpr(v){const parts=String(v).replace(/,/g,'.').replace(/\s/g,'').split('+').filter(Boolean);if(!parts.length)return 0;let sum=0;for(const x of parts){const n=Number(x);if(!Number.isFinite(n)||n<0)return NaN;sum+=n}return Math.round(sum*100)/100}
function refillExprOf(t){const e=t.refillExpr;return e&&e.includes('+')&&sumExpr(e)===Number(t.refill)?e:''}
function refillText(t){return t.refill?String(t.refill).replace('.',','):''}
function refillSumText(t,editing){const e=refillExprOf(t);if(!e)return '';return editing?'= '+num(sumExpr(e))+' л':e.split('+').filter(Boolean).join(' + ')}
function fitInput(el){const ph=!el.value;if(ph)el.value=el.placeholder||'0';el.style.width='1px';const w=el.scrollWidth;if(ph)el.value='';el.style.width=w+2+'px'}
function tankMax(){const t=state.travel;return Math.max(0,Math.min(TANK,Number(t.startFuel||0)+Number(t.refill||0)))}
const TANK_STEP=5;function setTank(v){const t=state.travel,avail=tankMax();let x=Math.max(0,Math.min(TANK,Number(v)));if(x>avail+1e-9){x=Math.floor(avail/TANK_STEP)*TANK_STEP;toast(`Більше ніж ${num(round(avail,1))} л у баку бути не може: стільки було на виїзді разом із заправкою.`)}t.endTarget=x}
const prevRecord=t=>previousMonthRecord(fuelRows,{...t,plate:''});const hasPrevious=()=>!!prevRecord(state.travel);
function setMonth(month){const bounds=monthBounds(month);if(!bounds)return toast('Виберіть коректний місяць.');Object.assign(state.travel,bounds);state.travel.rows.forEach(row=>row.date=bounds.from);state.travel.refill=0;state.travel.realKm='';state.travel.adjustmentKm=0;delete state.travel.autoBasisMonth;return previousFuel().then(()=>{save();render()})}
const MONTH_GRADIENTS=['linear-gradient(135deg,#3b6fd8 0%,#5b5bd6 50%,#7a4fd0 100%)','linear-gradient(135deg,#5a7fe0 0%,#7b6fe0 50%,#a06bd8 100%)','linear-gradient(135deg,#7fa8f0 0%,#8f8fe8 50%,#c07ad8 100%)','linear-gradient(135deg,#3fbf9a 0%,#2ea69a 50%,#2b8aa0 100%)','linear-gradient(135deg,#5cc46e 0%,#2fae7a 50%,#1f9488 100%)','linear-gradient(135deg,#8ccf4a 0%,#4fb85a 50%,#239a6a 100%)','linear-gradient(135deg,#ffb347 0%,#ff8a4c 50%,#f5605a 100%)','linear-gradient(135deg,#ff9a6b 0%,#f5605a 50%,#d9365e 100%)','linear-gradient(135deg,#ffa24c 0%,#f26a5a 50%,#d9407a 100%)','linear-gradient(135deg,#f2a93b 0%,#e07a2e 50%,#c0532a 100%)','linear-gradient(135deg,#e8833a 0%,#c8552e 50%,#9e3a3a 100%)','linear-gradient(135deg,#9b7bb8 0%,#7a5f9e 50%,#4f4f7e 100%)'];const monthTint=from=>{const m=Number(String(from||'').slice(5,7));return m>=1&&m<=12?(MONTH_GRADIENTS[m%12].match(/#[0-9a-f]{6}(?= 50%)/i)||[''])[0]||'var(--accent)':'var(--accent)'};const monthHero=from=>{const m=Number(String(from||'').slice(5,7));return m>=1&&m<=12?` style="--hero:${MONTH_GRADIENTS[m%12]}"`:''};
const TANK=40,CITY='Київ',ROUTES=[{route:'Львів – Тернопіль – Львів',km:260},{route:'Львів – Хмельницький – Львів',km:480}];
const shiftMonth=(from,d)=>{const x=new Date(from.slice(0,7)+'-15T12:00:00Z');x.setUTCMonth(x.getUTCMonth()+d);return x.toISOString().slice(0,7)};
function monthLocked(t=state.travel){return fuelRows.some(x=>sameCar(x.car,t.car)&&x.from>t.from)}
function syncStart(){const t=state.travel;if(!fuelLoaded||fuelRows.some(x=>x.from===t.from&&sameCar(x.car,t.car)))return;const row=prevRecord(t);if(!row)return;const r=travelCalc(row);if(r.error)return;if(t.odometer!==r.endOdo||t.startFuel!==r.endFuel){Object.assign(t,{odometer:r.endOdo,startFuel:r.endFuel,rate:row.rate,autoBasisMonth:t.from.slice(0,7),basis:'попередній місяць '+row.from.slice(0,7)});Object.assign(t,filledTravel(t));save()}}
function travelView(){if(!fuelLoaded){if(!fuelView.loading){fuelView.loading=true;loadFuel().then(()=>{fuelView.loading=false;if(view==='travel'||view==='fuel')render()})}return {title:'Подорожній лист',body:`<div class="skel skel-hero"></div><div class="skel skel-row" style="height:110px"></div><div class="skel skel-row" style="height:120px"></div><div class="skel skel-row" style="height:150px"></div>`}}prepareMonthly();syncStart();if(!fuelLoaded)loadFuel().then(ok=>{if(ok&&view==='travel')render();});
 const t=state.travel,locked=fuelLoaded&&monthLocked(t),prev=hasPrevious(),realOdo=t.realKm===''||t.realKm==null?'':round(Number(t.odometer)+Number(t.realKm));return {locked,title:'Подорожній лист',right:locked?`<button class="round ghost lock-top" data-action="lock-info" aria-label="Місяць закрито">${icon('lock')}</button>`:`<button class="text-btn" data-action="save-month">Зберегти</button>`,
 body:`<section class="hero fuel-hero"${monthHero(t.from)}><div class="month-switch"><button class="round glass" data-action="month-prev" aria-label="Попередній місяць">${icon('left')}</button><b>${esc(monthName(t.from).replace(/ р\.$/,''))}</b><button class="round glass" data-action="month-next" aria-label="Наступний місяць">${icon('right')}</button></div><span class="hero-label">Пробіг за місяць</span><div class="km-wrap"><div class="hero-amount" id="km-total"></div></div><div class="hero-status" id="fuel-status"></div></section>
 <section class="fuel-input"><label for="refill-input">Заправлено за місяць</label><div class="amount-input"><input id="refill-input" type="text" inputmode="decimal" autocomplete="off" data-refill value="${esc(refillText(t))}" style="width:${refillText(t).length||1}.6ch" placeholder="0"><span>л</span><button type="button" class="refill-plus" data-action="refill-plus" aria-label="Додати ще заправку">+</button></div><p class="hint center" id="refill-sum">${refillSumText(t,false)}</p></section>
 <section class="journey"><div class="j-head"><span></span><span>Виїзд</span><span></span><span>Приїзд</span></div><div class="j-row"><span>${icon('fuel')}Бак</span><b id="j-fuel-start"></b><i>→</i><b id="j-fuel-end"></b></div><div class="j-row"><span>${icon('car')}Одометр</span><b id="j-odo-start"></b><i>→</i><b id="j-odo-end"></b></div></section>
 ${prev?'':`<section class="fuel-input start"><label>Стартові дані</label><p class="hint" style="margin:2px 0 10px">Звіту за попередній місяць немає. Вкажіть, з чим виїжджаєте на початку місяця.</p><div class="field-grid">${field('Одометр, км','travel.odometer',t.odometer,'number','min="0" step="0.1" inputmode="decimal"')}${field('У баку, л','travel.startFuel',t.startFuel,'number','min="0" max="40" step="0.5" inputmode="decimal"')}</div></section>`}
 <section class="fuel-input tank"><div class="tank-head"><label for="tank-range">У баку по приїзді</label><b id="tank-value"></b></div><div class="tank-scale"><span>0</span><span>20</span><span>40 л</span></div><div class="tank-row"><button class="round soft" data-action="tank-minus" aria-label="Менше на 5 л">−</button><div class="tank-track"><i class="tank-zone"></i><i class="tank-lock"></i><input id="tank-range" type="range" min="0" max="${TANK}" step="${TANK_STEP}" data-tank value="${esc(t.endTarget)}"></div><button class="round soft" data-action="tank-plus" aria-label="Більше на 5 л">+</button></div><div class="card-foot center">${btn('Поставити по центру · 20 л','tank-center','link')}</div></section>
 <section class="fuel-input"><label for="real-odo">Одометр на приладі зараз <small>· необов’язково</small></label><div class="field-row"><input id="real-odo" type="number" inputmode="decimal" min="0" step="0.1" data-real-odo value="${realOdo}" placeholder="Щоб звірити з розрахунком"></div><div id="real-comparison"></div></section>
 ${group('Для бланка',`<div class="sheet" id="sheet"></div><div class="card-foot">${btn(icon('eye')+'Переглянути бланк','travel-preview','link')}</div>`)}
 <details class="group more"><summary>Поїздки · необов’язково</summary><div class="card"><div class="route-chips">${ROUTES.map((x,i)=>`<button class="chip" data-add-route="${i}">${icon('plus')}${esc(x.route.replace(/ – Львів$/,''))} · ≈${x.km} км</button>`).join('')}</div><div id="trip-rows">${tripRows()}</div><button class="add-row" data-action="add-trip">${icon('plus')}Інша поїздка</button>${t.rows.length>1?`<div class="card-foot">${btn('Розподілити порівну','split-trips','link')}</div>`:''}</div></details>
 ${prev?`<details class="group more"><summary>Початкові дані</summary><div class="card"><div class="field-grid">${field('У баку при виїзді, л','travel.startFuel',t.startFuel,'number','min="0" max="40" step="0.01" inputmode="decimal"')}${field('Одометр при виїзді, км','travel.odometer',t.odometer,'number','min="0" step="0.01" inputmode="decimal"')}${field('Додатковий пробіг, км','travel.adjustmentKm',t.adjustmentKm,'number','min="0" step="0.1" inputmode="decimal"')}</div>${previousLine()}</div></details>`:''}`,
 bar:`<button class="button pill secondary" data-action="travel-preview">${icon('eye')}Переглянути бланк</button>`}}
function presetSummary(){const p=state.preset;return `<div class="stat-grid two"><div><span>Препарати</span><b>${p.products.length?p.products.map(esc).join(', '):'—'}</b></div><div><span>Витрати</span><b>${p.items.length?p.items.map(r=>esc(r.name)+(Number(r.price)?' · '+money(Number(r.qty)*Number(r.price))+' ₴':'')).join('<br>'):'—'}</b></div></div>`}
function eventSettingsView(){const p=state.preset;return {title:'Дані за замовчуванням',body:`<p class="hint" style="margin:0 2px 18px">Ці дані автоматично підставляються в кожен новий круглий стіл. Змінити їх у конкретному звіті можна там же.</p>
 ${group('Типові дані',`${pickField('Відповідальна особа, у давальному відмінку','preset.person',p.person,'representatives','preset','maxlength="180" placeholder="Кузьмінській Уляні Іванівні"')}`)}
 ${group('Препарати і витрати',`${presetSummary()}<p class="hint">Відмітьте препарати й позиції витрат на екрані події, потім натисніть кнопку нижче.</p>`)}
 <div class="stack">${btn(icon('save')+'Запам’ятати з поточної події','preset-from-event','button secondary')}${btn(icon('check')+'Заповнити поточну подію','preset-apply','button')}</div>`}}
function applyPreset(e){const p=state.preset;e.city=CITY;if(p.person){e.person=p.person;if(p.representativeId)e.representativeId=p.representativeId}if(p.products.length)e.products=[...p.products];if(p.items.length)e.items=structuredClone(p.items);return e}
function carSettingsView(){const t=state.travel;return {title:'Авто і норма',body:`<p class="hint" style="margin:0 2px 18px">Ці дані не змінюються щомісяця й автоматично підставляються в подорожній лист.</p>
 ${group('Автомобіль',`<div class="field-grid">${field('Марка','travel.car',t.car,'text','maxlength="120"')}${field('Держномер','travel.plate',t.plate,'text','maxlength="30"')}</div>${field('Норма витрати, л/100 км','travel.rate',t.rate,'number','min="0.01" step="0.01" inputmode="decimal"')}`)}
 ${group('Водій',`${pickField('ПІБ водія','travel.driver',t.driver,'representatives','travel','maxlength="180"')}`)}
 ${group('Реквізити бланка',`<div class="field-grid">${field('Номер листа','travel.number',t.number||'','text','maxlength="30"')}${field('Режим роботи','travel.workMode',t.workMode||'','text','maxlength="80"')}${field('Марка пального','travel.fuelBrand',t.fuelBrand||'','text','maxlength="30"')}${field('Код марки','travel.fuelCode',t.fuelCode||'','text','maxlength="20"')}${field('Час виїзду','travel.departTime',t.departTime||'','time')}${field('Час повернення','travel.returnTime',t.returnTime||'','time')}${field('Годин у наряді','travel.hours',t.hours||'','number','min="0" step="0.1"')}${field('Колона','travel.column',t.column||'','text','maxlength="30"')}${field('Бригада','travel.brigade',t.brigade||'','text','maxlength="30"')}</div>${field('Особливі відмітки','travel.notes',t.notes||'','text','maxlength="300"')}`)}`}}
function tripRows(){const result=travelCalc(state.travel);return state.travel.rows.map((r,i)=>{const last=i===state.travel.rows.length-1;return `<div class="trip"><div class="trip-top"><b>Поїздка ${i+1}</b>${last?'<span class="tag">решта пробігу</span>':''}<button class="icon-btn" data-remove-trip="${i}" aria-label="Видалити поїздку ${i+1}" ${state.travel.rows.length===1?'disabled':''}>${icon('x')}</button></div><input aria-label="Маршрут поїздки ${i+1}" placeholder="Маршрут (необов’язково)" data-trip="${i}" data-prop="route" value="${esc(r.route)}" maxlength="200"><div class="field-grid"><label class="field"><span>Дата</span><input type="date" data-trip="${i}" data-prop="date" value="${esc(r.date)}"></label><label class="field"><span>Пробіг, км</span><div class="stepper">${last?'':`<button data-step-trip="${i}" data-step="-1" aria-label="Зменшити пробіг поїздки ${i+1}">−</button>`}<input type="number" min="0" step="0.01" inputmode="decimal" aria-label="Пробіг поїздки ${i+1}" data-trip="${i}" data-prop="km" value="${last?result.rows?.[i]?.km??0:r.km}" ${last?'readonly data-last-km':''}>${last?'':`<button data-step-trip="${i}" data-step="1" aria-label="Збільшити пробіг поїздки ${i+1}">+</button>`}</div></label></div></div>`}).join('')}

/* ---------- Аналітика пального ---------- */
const sameCar=(a,b)=>String(a||'').trim().toUpperCase()===String(b||'').trim().toUpperCase();
function lastHero(last){if(!last)return `<section class="hero"><span class="hero-label">Після повернення</span><div class="hero-amount">— <small>км</small></div><div class="hero-stats two"><div><span>У баці</span><b>—</b></div><div><span>Нестиковка</span><b>—</b></div></div></section>`;const r=fuelMetrics(last),name=new Date(last.from.slice(0,7)+'-15T12:00:00').toLocaleDateString('uk-UA',{month:'long'}),d=r.realDifference,rate=Number(last.rate);
 const cls=d===null?'':d<0?'bad':d>0?'good':'even',label=d===null?'Нестиковка':d<0?'Брак':d>0?'Запас':'Нестиковка',val=d===null?'—':d===0?'Немає':`${d<0?'−':'+'}${num(Math.abs(d))} км`;
 const why=d===null?`За ${esc(name)} не вводили показ одометра на приладі, тому звірити немає з чим. Його можна вказати в самому місяці, поле «Одометр на приладі».`:d===0?'Пробіг у бланку точно збігається з одометром на приладі.':d<0?`У бланку за ${esc(name)} записано ${num(r.total)} км, а на приладі проїхано лише ${num(r.realKm)} км. Пробіг у бланку рахується з витраченого пального за нормою ${num(rate)} л/100, тож ${num(-d)} км у бланку одометр не підтверджує. Реально машина витратила більше за норму: ≈${num(round(r.realRate,1))} л/100 км. Це погано.`:`На приладі проїхано ${num(r.realKm)} км, а в бланку записано ${num(r.total)} км, тобто на ${num(d)} км менше. Реальна витрата нижча за норму: ≈${num(round(r.realRate,1))} л/100 км замість ${num(rate)}. Це в межах норми.`;
 return `<section class="hero"${monthHero(last.from)}><span class="hero-label">Одометр після повернення · ${esc(name)}</span><div class="hero-amount"><span data-odo="${r.endOdo}" data-odo-key="root"></span> <small>км</small></div><div class="hero-stats two"><div><span>У баці</span><b>${num(r.endFuel)} л</b></div><button class="diff-tile ${cls}" data-action="diff-why" aria-expanded="false"><span>${label}</span><b>${val}</b></button></div><p class="diff-why" id="diff-why" hidden>${why}</p></section>`}
function fuelView(){if(!fuelLoaded&&!fuelView.loading){fuelView.loading=true;loadFuel().then(()=>{fuelView.loading=false;if(view==='fuel')render()})}
 if(!fuelLoaded)return {body:`<header class="large-title"><div><small>&nbsp;</small><h1>Подорожній</h1></div></header><div class="skel skel-hero"></div><div class="skel-title skel"></div><div class="skel skel-row"></div><div class="skel skel-row"></div><div class="skel skel-row"></div>`};
 const rows=fuelRows.filter(x=>sameCar(x.car,state.travel.car)).sort((a,b)=>b.from.localeCompare(a.from)),year=today().slice(0,4),years=[...new Set([year,...rows.map(t=>t.from.slice(0,4))])].sort().reverse();
 const t=state.travel,draftSaved=rows.some(x=>x.from===t.from),draft=!draftSaved&&Number(t.refill)>0;
 const item=t=>{const r=fuelMetrics(t);return `<button class="row" data-action="fuel-open" data-index="${fuelRows.indexOf(t)}"><span class="avatar travel">${icon('fuel')}</span><span class="row-main"><b>${esc(new Date(t.from.slice(0,7)+'-15T12:00:00').toLocaleDateString('uk-UA',{month:'long',year:'numeric'}).replace(/ р\.$/,'').replace(/^./,c=>c.toUpperCase()))}</b><small>${num(r.refill)} л · ${fraction(r.actualRate,t.liters)}</small></span><span class="row-amount">${num(r.total)} км</span>${icon('right','chev')}</button>`};
 return {body:`<header class="large-title"><div><small>${esc([t.car,t.plate].filter(Boolean).join(' · '))}</small><h1>Подорожній</h1></div></header>
 ${lastHero(rows[0])}
 ${draft?`<button class="tile wide" data-action="fuel-continue"><span class="tile-icon">${icon('pen')}</span><span class="tile-text"><b>Продовжити ${esc(monthName(t.from).replace(/ р\.$/,''))}</b><small>Чернетка ще не збережена</small></span>${icon('right','chev')}</button>`:''}
 ${!fuelLoaded?`<p class="hint center">Завантажуємо місяці…</p>`:rows.length?`<section class="group"><h2 class="group-title">Місяці</h2><div class="card">${rows.map(item).join('')}</div></section>`:`<section class="group"><div class="card empty">${icon('fuel','big')}<b>Ще немає збережених місяців</b><p>Натисніть «Новий місяць» внизу.</p></div></section>`}
 ${session.user.role==='admin'?`<details class="group more"><summary>Імпорт історії</summary><div class="card">${row('upload','Імпортувати історію','З Excel і зразка, без заміни наявних записів','fuel-import')}</div></details>`:''}`,
 bar:`<button class="button pill" data-action="fuel-new">${icon('plus')}Новий місяць</button>`}}

/* ---------- Звіти ---------- */

/* ---------- Профіль ---------- */
function profileView(){const p=state.profile,u=session.user;return {body:`<header class="large-title"><div><small>${u.role==='admin'?'Адміністратор':'Представник'}</small><h1>Профіль</h1></div></header>
 <section class="group"><div class="card"><div class="account"><span class="avatar big-av">${esc((u.name||'?').trim().charAt(0).toUpperCase())}</span><span class="row-main"><b>${esc(u.name)}</b><small>${esc(u.username)}</small></span></div>${u.role==='admin'?row('users','Користувачі','Доступ для представників','accounts'):''}${row('key','Змінити пароль','Від 12 символів','open-password')}</div></section>
 ${group('Круглий стіл',row('sliders','Дані за замовчуванням','Відповідальна особа, препарати, витрати','event-settings')+row('pen','Підписант',esc(p.head+' · '+p.position),'open-signer')+row('building','Клініки',plural(state.clinics.length,'запис','записи','записів'),'contacts-clinics')+row('user','Представники',plural(state.representatives.length,'запис','записи','записів'),'contacts-representatives'))}
 ${group('Подорожній лист',row('car','Авто і норма',esc([state.travel.car,state.travel.plate,state.travel.rate?state.travel.rate+' л/100':''].filter(Boolean).join(' · ')),'car-settings')+row('user','Водій',esc(state.travel.driver||'Не вказано'),'car-settings')+row('download','Вивантажити місяці','JSON-файл з усіма місяцями подорожнього','fuel-export')+row('upload','Завантажити місяці','Додасть місяці з файлу, наявні не змінить','fuel-import-file'))}
 ${group('Дані',row('download','Завантажити резервну копію','JSON-файл зі звітами й довідниками','backup')+row('upload','Відновити з копії','Замінить поточні дані','restore')+(standalone?'':row('phone','Встановити на телефон','Іконка на головному екрані','install')))}
 <section class="group"><div class="card">${`<button class="row danger" data-action="logout"><span class="avatar">${icon('logout')}</span><span class="row-main"><b>Вийти</b></span></button>`}</div></section>
 <p class="foot-note">${storageOK?'Звіти й довідники зберігаються в цьому браузері, місячні записи пального — на сервері. Робіть резервну копію перед зміною пристрою.':'Локальне збереження недоступне. Завантажте резервну копію, щоб не втратити дані.'}</p>`}}
function signerView(){return {title:'Підписант',body:group('',`${field('Організація','profile.company',state.profile.company,'text','maxlength="200"')}${field('Посада','profile.position',state.profile.position,'text','maxlength="120"')}${field('Підпис у наказі','profile.head',state.profile.head,'text','maxlength="100"')}${field('Підпис у кошторисі','profile.budgetHead',state.profile.budgetHead,'text','maxlength="100"')}`)+'<p class="foot-note">Зміни застосовуються до нових документів.</p>'}}
function passwordView(){return {title:'Зміна пароля',body:group('',`<label class="field"><span>Поточний пароль</span><input id="current-password" type="password" autocomplete="current-password" maxlength="256"></label><label class="field"><span>Новий пароль · від 12 символів</span><input id="new-password" type="password" autocomplete="new-password" minlength="12" maxlength="256"></label><label class="field"><span>Повторіть новий пароль</span><input id="repeat-password" type="password" autocomplete="new-password" maxlength="256"></label>`)+'<p class="foot-note">Після зміни пароля потрібно буде увійти знову.</p>',bar:`<button class="button pill" data-action="change-password">Змінити пароль</button>`}}

/* ---------- Користувачі (адміністратор) ---------- */
let accountRows=[];
function accountsView(){if(session.user.role!=='admin')return {title:'Користувачі',body:''};return {title:'Користувачі',right:`<button class="round ghost" data-action="accounts" aria-label="Оновити">${icon('back')}</button>`,body:`
 ${group('Новий представник',`<label class="field"><span>ПІБ</span><input id="account-name" maxlength="180" autocomplete="name"></label><label class="field"><span>Логін · латиниця, цифри, . _ @ -</span><input id="account-username" maxlength="80" autocomplete="off" autocapitalize="none" spellcheck="false"></label><label class="field"><span>Початковий пароль · від 12 символів</span><input id="account-password" type="password" minlength="12" maxlength="256" autocomplete="new-password"></label><p class="hint">Передайте пароль особисто. Представник змінить його в профілі.</p><div class="form-actions single">${btn('Створити обліковий запис','create-account')}</div>`)}
 ${group('Усі користувачі',accountRows.map(r=>`<div class="account-item"><div class="account"><span class="avatar">${icon('user')}</span><span class="row-main"><b>${esc(r.name)}</b><small>${esc(r.username)} · ${r.role==='admin'?'Адміністратор':'Представник'} · ${r.active?'активний':'призупинено'}</small></span>${r.id===session.user.id?'<span class="tag">Це ви</span>':''}</div>${r.id===session.user.id?'':`<div class="account-actions"><button class="chip" data-action="toggle-account" data-id="${esc(r.id)}">${r.active?'Призупинити':'Відновити доступ'}</button><button class="chip" data-action="seed-account" data-id="${esc(r.id)}">Завантажити історію подорожніх</button><details><summary class="chip">Скинути пароль</summary><div class="inline-add"><input type="password" id="reset-${esc(r.id)}" placeholder="Новий пароль, від 12 символів" autocomplete="new-password" minlength="12" maxlength="256"><button class="button small" data-action="reset-account-password" data-id="${esc(r.id)}">Зберегти</button></div></details></div>`}</div>`).join(''))}`}}
async function showAccounts(){try{const data=await api('/api/users');accountRows=data.users;if(view==='accounts')render();else go('accounts');}catch(e){toast(e.message);}}
async function createAccount(){const button=document.querySelector('[data-action="create-account"]');button.disabled=true;try{await api('/api/users',{name:$('#account-name').value.trim(),username:$('#account-username').value.trim(),password:$('#account-password').value});await showAccounts();toast('Обліковий запис представника створено.');}catch(e){toast(e.message);button.disabled=false;}}
async function editAccount(action,id){try{const body=action==='toggle-account'?{active:!accountRows.find(row=>row.id===id).active}:{password:document.getElementById('reset-'+id).value};await api('/api/users/'+id,body,'PATCH');await showAccounts();toast(action==='toggle-account'?'Доступ оновлено.':'Пароль змінено. Попередні сесії завершено.');}catch(e){toast(e.message);}}
async function changePassword(){const password=$('#new-password').value;if(password!==$('#repeat-password').value)return toast('Нові паролі не збігаються.');try{await api('/api/password',{currentPassword:$('#current-password').value,password});await logout();}catch(e){toast(e.message);}}

/* ---------- Довідники ---------- */
const emptyContact=kind=>Object.fromEntries(directoryFields[kind].map(key=>[key,'']));
const contactDrafts={clinics:emptyContact('clinics'),representatives:emptyContact('representatives')};
const contactForm={clinics:false,representatives:false};
const inDirectory=kind=>{const e=state.event,lc=x=>String(x||'').trim().toLocaleLowerCase('uk');return kind==='clinics'?state.clinics.some(r=>lc(r.name)===lc(e.venue)&&lc(r.city)===lc(e.city)):state.representatives.some(r=>lc(r.person)===lc(e.person))};
function contactPicker(kind,target='event'){
 const clinic=kind==='clinics', current=state[target], rows=state[kind];
 if(!rows.length)return `<div class="picker-empty-wrap"><button class="row picker-empty" data-action="contacts-${kind}"><span class="avatar">${icon(clinic?'building':'user')}</span><span class="row-main"><b>${clinic?'Довідник клінік порожній':'Довідник представників порожній'}</b><small>Додайте запис, щоб потім вибирати його тут</small></span>${icon('right')}</button></div>`;
 const selected=rows.find(r=>r.id===current[clinic?'clinicId':'representativeId']&&(clinic?r.name===current.venue&&r.city===current.city:target==='travel'?r.name===current.driver:r.person===current.person));
 return `<label class="field picker"><span>${target==='travel'?'Водій із представників':'Із довідника'}</span><select data-contact-picker="${kind}" data-target="${target}"><option value="">Ввести вручну</option>${rows.map(r=>`<option value="${esc(r.id)}" ${selected?.id===r.id?'selected':''}>${esc(r.name)}${clinic&&r.city?' · '+esc(r.city):''}</option>`).join('')}</select></label>`;
}
function contactsView(){
 const kind=contactKind,clinic=kind==='clinics',draft=contactDrafts[kind];
 const labels={name:clinic?'Назва клініки':'ПІБ представника',city:'Місто',address:'Адреса',contact:'Контактна особа',phone:'Телефон',person:'ПІБ у давальному відмінку'};
 const form=contactForm[kind]||draft.id?group(draft.id?'Редагування':'Новий запис',`${directoryFields[kind].map(key=>`<label class="field"><span>${labels[key]}</span><input data-directory="${kind}" data-contact-field="${key}" value="${esc(draft[key])}" maxlength="300" type="${key==='phone'?'tel':'text'}"></label>`).join('')}<div class="form-actions">${btn('Скасувати','cancel-'+kind,'button secondary')}${btn(draft.id?'Зберегти':'Додати','save-'+kind)}</div>`):'';
 return {title:'Довідники',body:`<div class="segmented"><button data-ckind="clinics" class="${clinic?'selected':''}">Клініки</button><button data-ckind="representatives" class="${clinic?'':'selected'}">Представники</button></div>
 ${form}
 <section class="group"><div class="card">${form?'':`<button class="add-row top" data-action="add-contact">${icon('plus')}Додати ${clinic?'клініку':'представника'}</button>`}${state[kind].map(r=>`<div class="row-wrap"><button class="row" data-edit-contact="${esc(r.id)}" data-contact-kind="${kind}"><span class="avatar">${icon(clinic?'building':'user')}</span><span class="row-main"><b>${esc(r.name)}</b><small>${[clinic?r.city:r.person,clinic?r.address:'',r.phone].filter(Boolean).map(esc).join(' · ')||'&nbsp;'}</small></span></button><button class="icon-btn" data-remove-contact="${esc(r.id)}" data-contact-kind="${kind}" aria-label="Видалити ${esc(r.name)}">${icon('x')}</button></div>`).join('')}${!state[kind].length&&!form?`<p class="hint pad">${clinic?'Назва й місто клініки підставляються в документи події.':'ПІБ підставляється у наказ і подорожній лист.'}</p>`:''}</div></section>`};
}
function saveContact(kind){
 const draft=contactDrafts[kind],row={id:draft.id||crypto.randomUUID(),...Object.fromEntries(directoryFields[kind].map(k=>[k,draft[k].trim()]))};
 if(!validDirectory([row],kind))return toast(kind==='clinics'?'Введіть назву клініки.':'Введіть ПІБ представника та ПІБ у давальному відмінку.');
 const index=state[kind].findIndex(r=>r.id===row.id);
 if(index<0&&state[kind].length>=500)return toast('У довіднику може бути до 500 записів.');
 if(index<0)state[kind].push(row);else state[kind][index]=row;
 contactDrafts[kind]=emptyContact(kind);contactForm[kind]=false;save();render();toast(storageOK?'Запис збережено.':'Не вдалося зберегти на пристрої. Завантажте резервну копію.');
}
function rememberContact(kind){
 const clinic=kind==='clinics',e=state.event,name=(clinic?e.venue:e.person).trim();
 if(!name)return toast(clinic?'Спочатку введіть назву клініки.':'Спочатку введіть відповідальну особу.');
 if(!clinic){
  const existing=state.representatives.find(r=>r.person.toLocaleLowerCase('uk')===name.toLocaleLowerCase('uk'));
  if(existing){applyContact(state,kind,existing.id);save();render();return toast('Представника вже збережено.');}
  contactDrafts.representatives={...emptyContact(kind),person:name};contactKind='representatives';contactForm.representatives=true;go('contacts');
  document.querySelector('[data-directory="representatives"]')?.focus();
  return toast('Додайте ПІБ у називному відмінку та збережіть запис.');
 }
 const row=state[kind].find(r=>r.name.toLocaleLowerCase('uk')===name.toLocaleLowerCase('uk')&&(!clinic||r.city.trim().toLocaleLowerCase('uk')===e.city.trim().toLocaleLowerCase('uk')));
 if(row){applyContact(state,kind,row.id);save();render();return toast('Такий запис уже збережено. Змінити його можна в довіднику.');}
 if(state[kind].length>=500)return toast('У довіднику може бути до 500 записів.');
 const record={...emptyContact(kind),id:crypto.randomUUID(),name,...(clinic?{city:e.city.trim()}:{person:name})};
 state[kind].push(record);applyContact(state,kind,record.id);save();render();toast(storageOK?'Дані збережено в довіднику.':'Не вдалося зберегти на пристрої. Завантажте резервну копію.');
}

/* ---------- Пальне на сервері ---------- */
async function loadFuel(){try{fuelRows=(await api('/api/fuel')).records;fuelLoaded=true;return true;}catch(e){toast(e.message);return false;}}
async function saveFuel(){prepareMonthly();if(monthLocked())throw Error('Цей місяць закрито: уже є наступний збережений місяць.');if(!validFuel(state.travel))throw Error('Перевірте місяць, автомобіль, залиті літри, залишки та пробіг. Витрата має бути більшою за нуль.');await api('/api/fuel',state.travel);await loadFuel();}
async function previousFuel(){if(!await loadFuel())return;prepareMonthly();const t=state.travel,row=prevRecord(t);if(!row){render();return toast('Немає запису за попередній місяць. Початкові дані залишено для ручного введення.');}const r=travelCalc(row);Object.assign(t,{odometer:r.endOdo,startFuel:r.endFuel,endTarget:r.endFuel,rate:row.rate,autoBasisMonth:t.from.slice(0,7),basis:'попередній місяць '+row.from.slice(0,7)});Object.assign(t,filledTravel(t));save();render();}

function stashDraft(){const t=state.travel;if(!fuelRows.some(x=>sameCar(x.car,t.car)&&x.from===t.from))state.travelDraft=structuredClone(t)}
let swapping=0;
const SKIP_LEAF='.hero-fade';
function leafMap(root){const m=new Map();(function walk(el,path){[...el.children].forEach((ch,i)=>{const p=path+'/'+i;if(ch.matches(SKIP_LEAF))return;if(!ch.children.length||ch.matches('svg,input,select,textarea,img,button.round')){m.set(p,{el:ch,sig:[ch.tagName,ch.className.baseVal??ch.className,ch.tagName==='svg'?ch.innerHTML:ch.textContent,ch.value??'',ch.getAttribute('style')||'',ch.disabled?1:0].join('|')});return}walk(ch,p)})})(root,'');return m}
async function monthSwap(){const old=$('#content'),y=scrollY,still=matchMedia('(prefers-reduced-motion: reduce)').matches,hero=old.querySelector('.fuel-hero'),bg=hero?getComputedStyle(hero).backgroundImage:'',id=++swapping,barRight=$('#appbar .appbar-right')?.innerHTML;
 old.classList.remove('enter','month-in');old.querySelectorAll('.fade-in').forEach(e=>e.classList.remove('fade-in'));
 if(still){render();scrollTo(0,y);return}
 const fresh=document.createElement('main');old.id='content-old';fresh.id='content';fresh.className=old.className;fresh.style.cssText=`position:absolute;visibility:hidden;width:${old.offsetWidth}px;pointer-events:none`;old.before(fresh);
 render.last=view+':'+fuelLoaded;render()
 const a=leafMap(old),b=leafMap(fresh),gone=[],come=[];
 a.forEach((v,k)=>{const w=b.get(k);if(!w||w.sig!==v.sig)gone.push(v.el)});b.forEach((v,k)=>{const w=a.get(k);if(!w||w.sig!==v.sig)come.push(v.el)});
 gone.forEach(e=>e.classList.add('fade-out'));
 const nr=$('#appbar .appbar-right');if(nr&&nr.innerHTML!==barRight){nr.classList.remove('fade-in');void nr.offsetWidth;nr.classList.add('fade-in')}
 await new Promise(r=>setTimeout(r,200));
 if(id!==swapping){old.remove();fresh.style.cssText='';return}
 come.forEach(e=>e.classList.add('fade-in'));old.remove();fresh.style.cssText='';scrollTo(0,y);
 const h=fresh.querySelector('.fuel-hero');if(h&&bg&&bg!=='none'&&getComputedStyle(h).backgroundImage!==bg){const o=document.createElement('div');o.className='hero-fade';o.style.backgroundImage=bg;h.prepend(o);requestAnimationFrame(()=>requestAnimationFrame(()=>o.classList.add('go')));setTimeout(()=>o.remove(),800)}
 setTimeout(()=>fresh.querySelectorAll('.fade-in').forEach(e=>e.classList.remove('fade-in')),500)}
async function goMonth(dir){await loadFuel();const t=state.travel,target=shiftMonth(t.from,dir),mine=fuelRows.filter(x=>sameCar(x.car,t.car)).sort((a,b)=>b.from.localeCompare(a.from)),rec=mine.find(x=>x.from.slice(0,7)===target);
 if(rec){stashDraft();state.travel={...defaults().travel,...structuredClone(rec)};state.travel.refill=travelCalc(rec).refill;state.travel.fuelMode='filled'}
 else if(state.travelDraft&&state.travelDraft.from.slice(0,7)===target&&sameCar(state.travelDraft.car,t.car)){state.travel=structuredClone(state.travelDraft)}
 else if(!mine.length||target===shiftMonth(mine[0].from,1)){stashDraft();await newMonth(false);return}
 else return toast(`За ${monthName(target+'-01').replace(/ р\.$/,'')} записів немає.`);
 save();monthSwap()}
async function newMonth(nav=true){await loadFuel();const t=state.travel,mine=fuelRows.filter(x=>sameCar(x.car,t.car)).sort((a,b)=>b.from.localeCompare(a.from)),last=mine[0];const month=last?shiftMonth(last.from,1):today().slice(0,7),bounds=monthBounds(month);const base={...bounds,liters:0,refill:0,realKm:'',fuelMode:'filled',adjustmentKm:0,rows:[{date:bounds.from,route:'',km:0}]};if(last){const r=travelCalc(last);Object.assign(t,base,{startFuel:r.endFuel,endTarget:r.endFuel,odometer:r.endOdo,rate:last.rate,autoBasisMonth:bounds.from.slice(0,7),basis:'попередній місяць '+last.from.slice(0,7)})}else Object.assign(t,base,{autoBasisMonth:bounds.from.slice(0,7)});save();docType='travel';fuelLoaded=true;if(nav){go('travel');setTimeout(()=>{const ri=$('#refill-input');if(ri&&!ri.disabled){ri.focus();ri.select?.()}},380)}else monthSwap()}
let finishing=false;
function upsertEvent(){const copy=structuredClone(state.event);if(!copy.archiveId)copy.archiveId=state.event.archiveId=crypto.randomUUID();const rec={id:copy.archiveId,type:'event',title:copy.venue,date:copy.date,data:copy,profile:structuredClone(state.profile)},i=state.archive.findIndex(r=>r.id===rec.id);if(i<0)state.archive.push(rec);else state.archive[i]=rec;save()}
function eventDone(){const errors=eventErrors(true);if(errors.length)return toast('Заповніть: '+errors.join(', ')+'.');upsertEvent();printDoc('order',true)}
/* ---------- Рендер ---------- */
const views={eventEdit:eventEditView,event:eventView,travel:travelView,fuel:fuelView,profile:profileView,contacts:contactsView,signer:signerView,password:passwordView,accounts:accountsView,carSettings:carSettingsView,eventSettings:eventSettingsView};
function render(){
 const v=views[view](),pushed=!!parentOf[view];
 document.body.dataset.view=view;document.body.classList.toggle('pushed',pushed);
 $('#appbar').innerHTML=pushed?`${v.left||`<button class="round ghost" data-action="back" aria-label="Назад">${icon('left')}</button>`}<b>${v.title}</b><span class="appbar-right">${v.right||''}</span>`:'';
 const sk=$('#content #boot-skel');if(sk){const r=sk.getBoundingClientRect();sk.style.cssText=`position:fixed;left:${r.left}px;top:${r.top}px;width:${r.width}px;bottom:0;z-index:25;pointer-events:none;background:var(--bg)`;document.body.append(sk);render.last=view+':'+fuelLoaded;requestAnimationFrame(()=>requestAnimationFrame(()=>sk.classList.add('gone')));setTimeout(()=>sk.remove(),450)}
 $('#content').innerHTML=v.body;
 {const key=view+':'+fuelLoaded,c=$('#content');if(key!==render.last){render.last=key;if(!inVT&&!matchMedia('(prefers-reduced-motion: reduce)').matches){c.classList.remove('enter');void c.offsetWidth;c.classList.add('enter');clearTimeout(render.t);render.t=setTimeout(()=>c.classList.remove('enter'),700)}}}
 $('#actionbar').innerHTML=v.bar||'';document.body.classList.toggle('has-bar',!!v.bar);
 const tab=rootOf(view);document.querySelectorAll('.tabbar [data-view]').forEach(el=>{el.classList.toggle('active',el.dataset.view===tab);el.setAttribute('aria-current',el.dataset.view===tab?'page':'false')});
 updateDerived();
 document.querySelectorAll('[data-odo]').forEach(el=>roll(el,Number(el.dataset.odo),el.dataset.odoKey));
 $('#content').classList.toggle('locked',!!v.locked);if(v.locked){$('#content').querySelectorAll('input,select,textarea,button:not([data-action=lock-info]):not([data-action^=month-])').forEach(el=>{el.disabled=true});$('#appbar').querySelectorAll('[data-action=car-settings]').forEach(el=>el.disabled=true)}
}
let inVT=false;function transition(dir,fn){if(dir==='tab'||!document.startViewTransition||matchMedia('(prefers-reduced-motion: reduce)').matches)return fn();document.documentElement.dataset.nav=dir;document.startViewTransition(()=>{inVT=true;try{fn()}finally{inVT=false}})}
function go(next){if(next===view)return render();const pushed=!!parentOf[next];view=next;if(next==='travel'){docType='travel';fuelLoaded=false}else if(next==='event')docType='order';pushed?history.pushState({view:next,pushed:true},''):history.replaceState({view:next},'');transition(pushed?'forward':'tab',()=>{render();window.scrollTo(0,0)})}
function back(){if(history.state?.pushed)history.back();else{view=parentOf[view]||'event';history.replaceState({view},'');render()}}
window.addEventListener('popstate',e=>{if($('#preview-dialog').open)$('#preview-dialog').close();view=e.state?.view||'event';if(view==='travel')docType='travel';transition('back',render)});

const odoMem={};
function rollDigits(el,value,key){if(!el)return;if(!Number.isFinite(value)){el.textContent='—';el.classList.remove('odo');odoMem[key]=undefined;return}
 const text=num(round(value)),prev=odoMem[key];odoMem[key]=round(value);
 const old=el.classList.contains('odo')&&el.dataset.text?el.dataset.text:(Number.isFinite(prev)?num(prev):null);
 el.className='odo';el.dataset.text=text;
 const up=!Number.isFinite(prev)||round(value)>=prev,o=old&&old.length===text.length?old:null,still=matchMedia('(prefers-reduced-motion: reduce)').matches;
 el.innerHTML=[...text].map((ch,i)=>{if(!/\d/.test(ch))return `<span class="odo-sep">${ch}</span>`;const was=o?o[i]:null;if(still||was===null||was===ch)return `<span class="odo-d"><span class="odo-strip"><span>${ch}</span></span></span>`;
  return `<span class="odo-d"><span class="odo-strip ${up?'up':'down'}"><span>${up?was:ch}</span><span>${up?ch:was}</span></span></span>`}).join('');
 if(!o&&!still&&!Number.isFinite(prev))el.classList.add('odo-in');
 setTimeout(()=>requestAnimationFrame(()=>el.querySelectorAll('.odo-strip.up,.odo-strip.down').forEach(st=>st.classList.add('go'))),0)}
function roll(el,value,key){if(!el)return;if(key==='root')return rollDigits(el,value,key);el.textContent=Number.isFinite(value)?num(round(value)):'—'}
function updateDerived(){
 if(view==='eventEdit'){const oe=eventErrors(false),be=eventErrors(true).filter(x=>!oe.includes(x)),os=$('#order-state'),bs=$('#budget-state'),mark=(el,errs,ok)=>{if(!el)return;el.closest('.doc-card').classList.toggle('ready',!errs.length);el.innerHTML=errs.length?'Бракує: '+esc(errs.join(', ')):icon('check')+ok};mark(os,oe,'Готовий до друку');mark(bs,oe.length?oe:be,money(costTotal(state.event.items))+' ₴');state.event.items.forEach((r,i)=>{const el=document.querySelector(`[data-line-total="${i}"]`);if(el)el.textContent=money(r.qty*r.price)+' ₴'});const errs=eventErrors(true),st=$('#preview-status');if(st){st.className='hero-status '+(errs.length?'warn':'ok');st.innerHTML=errs.length?'Заповніть: '+esc(errs.join(', ')):icon('check')+'Наказ і кошторис готові до друку'}const od=$('#order-date'),o=eventDates(state.event).orderDate;if(od)od.textContent='Дата наказу й кошторису ставиться автоматично на день раніше за дату чеку. Її можна змінити вручну.'}
 if(view==='travel'){prepareMonthly();const t=state.travel,r=fuelMetrics(t),v=(x,u='')=>x===undefined||x===null||!Number.isFinite(x)?'—':num(x)+u;
  const kt=$('#km-total');if(kt){if(!kt.querySelector('.odo-host'))kt.innerHTML='<span class="odo-host"></span> <small>км</small>';roll(kt.querySelector('.odo-host'),r.error||r.total===undefined?NaN:r.total,'km')}
  document.documentElement.style.setProperty('--ma',monthTint(t.from));
  const st=$('#fuel-status');if(st){const over=!r.error&&r.actualRate>Number(t.rate)+1e-9;st.className='hero-status '+(r.error||over?'warn':'ok');st.innerHTML=r.error?esc(!Number(t.refill)&&Number(t.startFuel)<=Number(t.endTarget)?'Введіть, скільки пального залили':r.error):over?'Фактична витрата більша за норму. Приберіть від’ємну поправку в «Початкових даних».':`${icon('check')}Фактично ${fraction(r.actualRate,Number(t.liters))} · норма ${fraction(Number(t.rate),r.normFuel)}`}
  const range=$('#tank-range');if(range){if(document.activeElement!==range)range.value=t.endTarget;const at=f=>`calc(14px + (100% - 28px) * ${Math.max(0,Math.min(1,f))})`,span=f=>`calc((100% - 28px) * ${Math.max(0,Math.min(1,f))})`;range.style.setProperty('--p',at(Number(t.endTarget)/TANK));const zone=document.querySelector('.tank-zone');if(zone){zone.style.left=at(15/TANK);zone.style.width=span(10/TANK)}const lock=document.querySelector('.tank-lock');if(lock){const f=tankMax()/TANK;lock.style.left=at(f);lock.style.width=f>=1?'0':`calc(100% - ${at(f)})`}}
  const ri=$('#refill-input');if(ri){ri.classList.toggle('expr',ri.value.includes('+'));ri.classList.toggle('long',ri.value.length>13);fitInput(ri)}const rs=$('#refill-sum');if(rs)rs.textContent=refillSumText(t,document.activeElement===ri);const tv=$('#tank-value');if(tv)tv.textContent=num(t.endTarget)+' л';
  
  [['#j-fuel-start',v(Number(t.startFuel),' л')],['#j-fuel-end',v(Number(t.endTarget),' л')],].forEach(([q,x])=>{const el=$(q);if(el)el.textContent=x});roll($('#j-odo-start'),Number(t.odometer),'os');roll($('#j-odo-end'),r.error?NaN:r.endOdo,'oe');const sh=$('#sheet');if(sh){const d=s=>s?new Date(s+'T12:00:00').toLocaleDateString('uk-UA'):'—';sh.innerHTML=[['Період',`${d(t.from)} – ${d(t.to)}`],['Автомобіль',esc([t.car,t.plate].filter(Boolean).join(' · ')||'—')],['Водій',esc(t.driver||'—')],['Залишок при виїзді',v(Number(t.startFuel),' л')],['Видано (заправлено)',v(Number(t.refill),' л')],['Залишок при поверненні',r.error?'—':v(r.endFuel,' л')],['Одометр при виїзді',v(Number(t.odometer))],['Одометр при поверненні',r.error?'—':v(r.endOdo)],['Пробіг',r.error?'—':v(r.total,' км')],['Витрата за нормою',r.error?'—':fraction(Number(t.rate),r.normFuel)],['Витрата фактична',r.error?'—':fraction(r.actualRate,Number(t.liters))],...(r.rows||[]).filter(x=>x.route.trim()).map((x,i)=>[`Поїздка ${i+1}`,`${esc(x.route)} · ${num(x.km)} км`])].map(([a,b])=>`<div><span>${a}</span><b>${b}</b></div>`).join('')}
  const rc=$('#real-comparison');if(rc)rc.innerHTML=r.realDifference===null||r.error?'<p class="hint">Лише для порівняння, у бланк не потрапляє.</p>':`<p class="hint">${r.realDifference===0?'Бланк і прилад збігаються.':r.realDifference<0?`<b class="bad-text">Брак −${num(-r.realDifference)} км</b>: у бланку більше кілометрів, ніж на приладі, реальна витрата вища за норму`:`<b>Запас +${num(r.realDifference)} км</b>: на приладі більше, ніж у бланку, витрата в межах норми`}${r.realDifference?` (${num(Math.abs(r.realPercent))}%)`:''}. Лише для інформації, у бланк не потрапляє.</p>`;
  const last=$('[data-last-km]');if(last)last.value=r.rows?.at(-1)?.km??0}
}
function eventErrors(budget){const e=state.event;let errors=[];if(!e.venue.trim())errors.push('назву закладу');if(!validDate(e.date))errors.push('дату круглого столу');if(!eventDates(e).orderDate)errors.push('дату чеку');if(!e.person.trim())errors.push('відповідальну особу');if(!e.products.length)errors.push('хоча б один препарат');if(budget&&(!e.items.length||e.items.some(r=>!r.name.trim()||!(Number(r.qty)>0)||Number(r.price)<0||!Number.isFinite(Number(r.price)))))errors.push('коректні позиції кошторису');return errors}
function travelErrors(){const t=state.travel,r=travelCalc(t);if([t.startFuel,t.endTarget].some(n=>Number(n)>TANK))return 'Залишок у баку може бути лише від 0 до 40 л.';if(r.error)return r.error;if([t.odometer,t.startFuel,t.endTarget].some(n=>!Number.isFinite(Number(n))||Number(n)<0))return 'Залишок, заправка й одометр мають бути невід’ємними.';if(!t.driver.trim()||!t.car.trim()||!t.plate.trim())return 'Заповніть водія, автомобіль і державний номер.';if(!t.from||!t.to||t.to<t.from)return 'Перевірте початок і кінець періоду.';if(t.rows.some(r=>r.route.trim()&&(!r.date||r.date<t.from||r.date>t.to)))return 'Дати поїздок мають бути в межах місяця.';return ''}
function documentHtml(type){const e=state.event,p=state.profile,d=eventDates(e).orderDate,val=s=>esc(s||'________________');if(type==='order')return `<article class="paper order"><h1>Н А К А З №${val(e.number)}</h1><div class="order-date"><span>м. ${val(e.city)}</span><span>${longDate(d)}</span></div><div class="order-subject">«Про організацію круглого столу<br>у ${val(e.venue)}»</div><p class="command">Наказую:</p><p>${val(e.person)} провести круглий стіл ${date(e.date)} року у ${val(e.venue)} по препаратах: ${val(e.products.join(', '))}</p><p class="order-point">1. &nbsp; Скласти кошторис.</p><p>Підстава: Розпорядження керівника.</p><div class="order-sign"><span>${val(p.position)}<br>${val(p.company)}</span><span>${val(p.head)}</span></div></article>`;if(type==='budget'){const total=money(costTotal(e.items));return `<article class="paper budget"><h1>К О Ш Т О Р И С</h1><p class="budget-subject">Про організацію круглого столу у ${val(e.venue)}</p><div class="amount-line">${total}</div><div class="amount-hint">( сума витрат подано в гривнях)</div><table><thead><tr><th>№</th><th>Опис затрат</th><th>Сума</th></tr></thead><tbody>${e.items.map((r,i)=>`<tr><td>${i+1}</td><td>${val(r.name)}</td><td class="amount">${money(r.qty*r.price)}</td></tr>`).join('')}<tr><td>&nbsp;</td><td></td><td></td></tr><tr><td>&nbsp;</td><td></td><td></td></tr><tr><td></td><td>Всього</td><td class="amount">${total}</td></tr></tbody></table><p class="budget-date">дата: ${date(d)}</p><p class="budget-sign">${val(p.position)}:__________________ ${val(p.budgetHead)}</p></article>`}const t=state.travel,r=travelCalc(t);return travelTemplate(t,r)}
function fitPreview(){const box=$('#full-preview');box.querySelectorAll('.preview-scale').forEach(el=>{const doc=el.firstElementChild;doc.style.transform='';const w=doc.offsetWidth,h=doc.offsetHeight,k=Math.min(1,(box.clientWidth-24)/w);doc.style.transformOrigin='0 0';doc.style.transform=`scale(${k})`;el.style.width=w*k+'px';el.style.height=h*k+'px'})}
function preview(type){docType=type;if(iosStandalone()){const ok=type==='travel'?!travelErrors():!eventErrors(true).length;if(ok)warmPdf(type==='travel'?documentHtml('travel'):documentHtml('order')+documentHtml('budget'))}$('#dialog-print').setAttribute('aria-label',type==='travel'?'Друк':'Друкувати обидва');$('#preview-title').textContent={order:'Наказ',budget:'Кошторис',travel:'Подорожній лист'}[type]||'';const dlg=$('#preview-dialog');$('#preview-switch').innerHTML=type==='travel'?'':`<div class="segmented small"><button data-doc="order" class="${type==='order'?'selected':''}">Наказ</button><button data-doc="budget" class="${type==='budget'?'selected':''}">Кошторис</button></div>`;const html=documentHtml(type);$('#full-preview').innerHTML=type==='travel'?html.split(/(?=<article)/).filter(Boolean).map(a=>`<div class="preview-scale">${a}</div>`).join(''):`<div class="preview-scale">${html}</div>`;if(!dlg.open)dlg.showModal();requestAnimationFrame(fitPreview)}
window.addEventListener('resize',()=>{if($('#preview-dialog').open)fitPreview()});
function printDoc(type,both=false){if(type==='travel'){const err=travelErrors();if(err)return toast(err)}else{const errors=eventErrors(type==='budget'||both);if(errors.length)return toast('Заповніть: '+errors.join(', ')+'.')}$('#page-style').textContent=`@page { size: ${type==='travel'?'A5':'A4'} portrait; margin: 0; }`;const html=both?documentHtml('order')+documentHtml('budget'):documentHtml(type);if(iosStandalone())return pdfPrint(html,pdfName(type,both));$('#print-root').innerHTML=html;document.body.classList.add('printing');window.print()}
function pdfName(type,both){if(type==='travel'){const t=state.travel;return 'Подорожній лист '+(t.from||'').slice(0,7)}return both?'Наказ і кошторис':type==='order'?'Наказ':'Кошторис'}
const pdfReady=new Map();function warmPdf(html){if(!iosStandalone())return;preparePdf(html).then(b=>{pdfReady.clear();pdfReady.set(html,b)}).catch(()=>{})}
async function pdfShare(blob,name){try{await sharePdf(blob,name)}catch(e){if(e?.name==='AbortError')return;if(e?.name==='NotAllowedError')return pdfButton(blob,name);toast(e?.message||'Не вдалося відкрити друк.')}}
function pdfButton(blob,name){document.querySelector('#pdf-ready')?.remove();const b=document.createElement('button');b.id='pdf-ready';b.className='button pill';b.textContent='Друкувати PDF';b.onclick=()=>{b.remove();pdfShare(blob,name)};document.body.append(b);setTimeout(()=>b.remove(),30000)}
async function pdfPrint(html,name){const ready=pdfReady.get(html);if(ready)return pdfShare(ready,name);toast('Готую PDF для друку…');try{const blob=await preparePdf(html);pdfReady.clear();pdfReady.set(html,blob);await pdfShare(blob,name)}catch(e){toast(e?.message||'Не вдалося підготувати PDF.')}}
window.addEventListener('afterprint',()=>document.body.classList.remove('printing'));
function storeReport(type){const errors=type==='event'?eventErrors(true).join(', '):travelErrors();if(errors)return toast(type==='event'?'Заповніть: '+errors:errors);const copy=structuredClone(type==='event'?state.event:state.travel);state.archive.push({id:crypto.randomUUID(),type,title:type==='event'?copy.venue:copy.driver,date:type==='event'?copy.date:copy.from,data:copy,profile:structuredClone(state.profile)});save();toast(storageOK?'Звіт збережено в архіві.':'Не вдалося зберегти. Завантажте резервну копію.');render()}
function downloadJson(data,name){const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
async function fuelExport(){if(!await loadFuel())return;if(!fuelRows.length)return toast('Ще немає збережених місяців.');downloadJson({version:1,fuel:fuelRows},`zvit-podorozhni-${today()}.json`);toast(`Вивантажено місяців: ${fuelRows.length}.`)}
async function fuelImport(f){try{if(f.size>5000000)throw Error('Файл завеликий.');const data=JSON.parse(await f.text()),list=Array.isArray(data)?data:data?.fuel;if(!Array.isArray(list)||!list.length)throw Error('У файлі немає місяців подорожнього.');if(!list.every(validFuel))throw Error('Деякі місяці у файлі мають невірний формат.');await loadFuel();const have=new Set(fuelRows.map(r=>(r.car||'')+'|'+r.from)),todo=list.filter(r=>!have.has((r.car||'')+'|'+r.from)).sort((x,y)=>x.from.localeCompare(y.from));if(!todo.length)return toast('Усі місяці з файлу вже є.');if(!confirm(`Додати місяців: ${todo.length}? Наявні місяці не зміняться.`))return;let added=0,failed=0;for(const m of todo){try{await api('/api/fuel',m);added++}catch(e){failed++}}fuelLoaded=false;await loadFuel();render();toast(`Додано місяців: ${added}${failed?`, не вдалося: ${failed} (пізніші місяці вже закриті)`:''}.`)}catch(e){toast('Не вдалося завантажити: '+e.message)}}
async function backup(){await loadFuel();downloadJson({...state,fuel:fuelRows},`zvit-backup-${today()}.json`)}
function validBackup(s){const str=x=>typeof x==='string'&&x.length<2000,arr=x=>Array.isArray(x)&&x.length<500,num=x=>Number.isFinite(Number(x))&&Number(x)>=0;const event=e=>e&&['venue','date','number','city','person'].every(k=>str(e[k]))&&(e.receiptDate===undefined||(str(e.receiptDate)&&(e.receiptDate===''||validDate(e.receiptDate))))&&arr(e.products)&&e.products.every(str)&&arr(e.items)&&e.items.every(r=>str(r.name)&&num(r.qty)&&num(r.price));const travel=t=>t&&['driver','car','plate','from','to'].every(k=>str(t[k]))&&['liters','rate','startFuel','refill','odometer'].every(k=>num(t[k]))&&(t.endTarget===undefined||num(t.endTarget))&&(t.adjustmentKm===undefined||Number.isFinite(Number(t.adjustmentKm)))&&arr(t.rows)&&t.rows.length>0&&t.rows.every(r=>str(r.date)&&str(r.route)&&num(r.km));const profile=p=>p&&['company','head','budgetHead','position'].every(k=>str(p[k]));return s?.version===1&&validDirectory(s.clinics,'clinics')&&validDirectory(s.representatives,'representatives')&&event(s.event)&&travel(s.travel)&&profile(s.profile)&&arr(s.products)&&s.products.every(str)&&arr(s.archive)&&s.archive.every(r=>str(r.id)&&/^[a-zA-Z0-9-]+$/.test(r.id)&&str(r.title)&&str(r.date)&&profile(r.profile)&&(r.type==='event'?event(r.data):r.type==='travel'&&travel(r.data)))&&(s.fuel===undefined||(arr(s.fuel)&&s.fuel.every(validFuel)))}
async function install(){if(deferredInstall){await deferredInstall.prompt();deferredInstall=null}else{toast('iPhone: Safari → Поділитися → На початковий екран. Android: меню → Встановити застосунок.')}}

