document.addEventListener('input',ev=>{const el=ev.target,ds=el.dataset;if(ds.refill!==undefined){const v=el.value.replace(/[^\d.,+\s]/g,'');if(v!==el.value)el.value=v;const n=sumExpr(v);if(Number.isNaN(n))return;state.travel.refill=n;if(v.includes('+'))state.travel.refillExpr=v.replace(/\s/g,'');else delete state.travel.refillExpr;save();updateDerived();return}if(ds.directory){contactDrafts[ds.directory][ds.contactField]=el.value;return}if(ds.tank!==undefined){setTank(el.value);el.value=state.travel.endTarget;prepareMonthly();save();updateDerived();return}if(ds.realOdo!==undefined){state.travel.realKm=el.value===''?'':round(Number(el.value)-Number(state.travel.odometer));save();updateDerived();return}if(ds.key){const [obj,key]=ds.key.split('.');state[obj][key]=key==='realKm'&&el.value===''?'':el.type==='number'||el.type==='range'?Number(el.value):el.value;if(obj==='travel'&&key==='adjustmentKm'&&state.travel.adjustmentKm<0){state.travel.adjustmentKm=0;el.value=0;toast('Фактична витрата не може бути більшою за норму, тому від’ємний пробіг не дозволено.')}if(ds.key==='travel.startFuel'&&el.value!==''&&(state.travel.startFuel<0||state.travel.startFuel>TANK)){state.travel.startFuel=Math.max(0,Math.min(TANK,state.travel.startFuel));el.value=state.travel.startFuel;toast('Залишок у баку може бути лише від 0 до 40 л.')}if(ds.key==='event.receiptDate'){const ev2=state.event;ev2.orderDate=previousDate(el.value);if(validDate(el.value))ev2.date=el.value;const oi=document.querySelector('[data-key="event.orderDate"]');if(oi)oi.value=ev2.orderDate}if(obj==='travel')prepareMonthly();save();updateDerived()}if(ds.item!==undefined){state.event.items[+ds.item][ds.prop]=ds.prop==='name'?el.value:Number(el.value);save();updateDerived()}if(ds.trip!==undefined&&!el.readOnly){state.travel.rows[+ds.trip][ds.prop]=ds.prop==='km'?Number(el.value):el.value;save();updateDerived()}});
document.addEventListener('change',async ev=>{if(ev.target.hasAttribute('data-fuel-month')){const bounds=monthBounds(ev.target.value);if(!bounds)return toast('Виберіть коректний місяць.');Object.assign(state.travel,bounds);state.travel.rows.forEach(row=>row.date=bounds.from);state.travel.refill=0;state.travel.realKm='';state.travel.adjustmentKm=0;delete state.travel.autoBasisMonth;await previousFuel();save();render();return;}if(ev.target.dataset.key==='travel.car'||ev.target.dataset.key==='travel.plate'){await previousFuel();return;}const picker=ev.target.dataset.contactPicker;if(picker){const target=ev.target.dataset.target||'event',val=ev.target.value;ev.target.value='';if(!val)return;if(val==='__save')return rememberContact(picker);if(val==='__open'){contactKind=picker;contactForm[picker]=true;return go('contacts')}if(target==='preset'){const row=state.representatives.find(r=>r.id===val);if(row)Object.assign(state.preset,{representativeId:val,person:row.person})}else applyContact(state,picker,val,target);state.event.city=CITY;save();render();return}if(ev.target.id==='fuel-file'){const f=ev.target.files[0];ev.target.value='';if(f)await fuelImport(f);return}if(ev.target.id!=='restore-file')return;try{const f=ev.target.files[0];if(!f)return;if(f.size>5000000)throw Error('Файл завеликий.');const incoming=JSON.parse(await f.text());if(!validBackup(incoming))throw Error('Невірний формат резервної копії.');if(confirm('Замінити всі поточні дані даними з резервної копії?')){const months=(incoming.fuel||[]).slice().sort((x,y)=>x.from.localeCompare(y.from));delete incoming.fuel;state=migrateDirectories(incoming);state.travel.endTarget??=state.travel.startFuel;state.travel.adjustmentKm??=0;save();let added=0,skipped=0;for(const m of months){try{await api('/api/fuel',m);added++}catch(e){skipped++}}if(months.length){fuelLoaded=false;await loadFuel()}render();toast(months.length?`Дані відновлено. Місяців подорожнього: ${added}${skipped?`, пропущено ${skipped}`:''}.`:'Дані відновлено.')}}catch(e){toast('Не вдалося відновити: '+e.message)}});
