function closeRowMenu(){document.querySelector('.row-menu')?.remove()}
function openRowMenu(btn,id){const was=document.querySelector('.row-menu')?.dataset.id===id;closeRowMenu();if(was)return;const m=document.createElement('div');m.className='row-menu';m.dataset.id=id;m.setAttribute('role','menu');m.innerHTML=`<button role="menuitem" data-duplicate-archive="${esc(id)}">${icon('copy')}Дублювати</button><button role="menuitem" class="danger" data-delete-archive="${esc(id)}">${icon('trash')}Видалити</button>`;document.body.append(m);const r=btn.getBoundingClientRect(),h=m.offsetHeight,below=r.bottom+6+h<innerHeight-80;m.style.top=(below?r.bottom+6:r.top-6-h)+scrollY+'px';m.style.right=Math.max(12,innerWidth-r.right)+'px'}
document.addEventListener('pointerdown',ev=>{if(!ev.target.closest('.row-menu,[data-row-menu]'))closeRowMenu()},true);
